//! PRD-17 section 2.2, rows T1, T2, T4 and T5: what the old run CA taught, as outcomes on the
//! `proxy::ca` API. PRD-03's `proxy_tls.rs` holds the handshake cases; they are not repeated.
//! T3 needs `proxy::serve` and is not here. Every key in this file is generated by the test.

use goalcup::proxy::ca::{BUNDLE_FILE, RUN_CA_FILE, RunCa, certificates};
use std::collections::BTreeSet;
use std::path::Path;
use x509_parser::extensions::{GeneralName, ParsedExtension};
use x509_parser::prelude::{FromDer as _, X509Certificate};

fn subtrees() -> Vec<String> {
    vec!["openai.com".to_string(), "anthropic.com".to_string()]
}

fn parse(der: &[u8]) -> X509Certificate<'_> {
    let (rest, cert) = X509Certificate::from_der(der).expect("a certificate");
    assert!(rest.is_empty());
    cert
}

fn extension<'a, 'b>(
    cert: &'b X509Certificate<'a>,
    pick: impl Fn(&'b ParsedExtension<'a>) -> bool,
) -> Option<(&'b ParsedExtension<'a>, bool)> {
    cert.iter_extensions()
        .find(|e| pick(e.parsed_extension()))
        .map(|e| (e.parsed_extension(), e.critical))
}

/// The key identifier in the leaf's Authority Key Identifier; the leaf must carry one.
fn aki_of(leaf_der: &[u8]) -> Vec<u8> {
    let cert = parse(leaf_der);
    let Some((ParsedExtension::AuthorityKeyIdentifier(aki), _)) = extension(&cert, |p| {
        matches!(p, ParsedExtension::AuthorityKeyIdentifier(_))
    }) else {
        panic!("the leaf has no Authority Key Identifier")
    };
    aki.key_identifier
        .as_ref()
        .expect("a key identifier")
        .0
        .to_vec()
}

/// T1: the leaf names the CA key in its Authority Key Identifier. Python 3.13 refuses a leaf
/// without it, so every Python harness would fail.
#[test]
fn leaf_aki_names_the_ca_key() {
    let ca = RunCa::mint(&subtrees()).unwrap();
    let ca_der = ca.cert_der().to_vec();
    let ca_cert = parse(&ca_der);
    let Some((ParsedExtension::SubjectKeyIdentifier(ski), _)) = extension(&ca_cert, |p| {
        matches!(p, ParsedExtension::SubjectKeyIdentifier(_))
    }) else {
        panic!("the CA has no Subject Key Identifier")
    };
    let leaf = ca.leaf("api.openai.com").unwrap();
    assert_eq!(aki_of(leaf.cert[0].as_ref()), ski.0);

    // The same holds for a CA that a later boot imported.
    let again = RunCa::import(&ca.export()).unwrap();
    let leaf = again.leaf("api.anthropic.com").unwrap();
    assert_eq!(aki_of(leaf.cert[0].as_ref()), ski.0);
}

/// T2: pathLen 0, critical name constraints from the host list, one hour back, about 8 days
/// valid; a leaf has one DNS SAN and serverAuth only. A leaked key cannot sign an unrelated name.
#[test]
fn ca_constraints_validity_and_leaf_shape() {
    let ca = RunCa::mint(&subtrees()).unwrap();
    let ca_der = ca.cert_der().to_vec();
    let cert = parse(&ca_der);

    let bc = cert
        .basic_constraints()
        .unwrap()
        .expect("basic constraints");
    assert!(bc.value.ca);
    assert_eq!(bc.value.path_len_constraint, Some(0));

    let Some((ParsedExtension::NameConstraints(nc), critical)) =
        extension(&cert, |p| matches!(p, ParsedExtension::NameConstraints(_)))
    else {
        panic!("the CA has no name constraints")
    };
    assert!(critical, "name constraints must be critical");
    let permitted: BTreeSet<String> = nc
        .permitted_subtrees
        .as_ref()
        .expect("permitted subtrees")
        .iter()
        .map(|s| match &s.base {
            GeneralName::DNSName(n) => (*n).to_string(),
            other => panic!("not a DNS subtree: {other:?}"),
        })
        .collect();
    assert_eq!(permitted, subtrees().into_iter().collect());
    assert!(nc.excluded_subtrees.is_none());

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64;
    let not_before = cert.validity().not_before.timestamp();
    let not_after = cert.validity().not_after.timestamp();
    assert!(
        (now - 3600 - not_before).abs() <= 120,
        "not_before is {} s from one hour back",
        now - 3600 - not_before
    );
    let span = not_after - not_before;
    let eight_days_and_an_hour = 8 * 86_400 + 3600;
    assert!(
        (span - eight_days_and_an_hour).abs() <= 120,
        "the window is {span} s"
    );

    let leaf = ca.leaf("API.OpenAI.com").unwrap();
    let leaf_cert = parse(leaf.cert[0].as_ref());
    let sans: Vec<String> = leaf_cert
        .subject_alternative_name()
        .unwrap()
        .expect("a SAN")
        .value
        .general_names
        .iter()
        .map(|n| match n {
            GeneralName::DNSName(d) => (*d).to_string(),
            other => panic!("not a DNS SAN: {other:?}"),
        })
        .collect();
    assert_eq!(sans, ["api.openai.com"]);
    let eku = leaf_cert
        .extended_key_usage()
        .unwrap()
        .expect("extended key usage")
        .value;
    assert!(eku.server_auth);
    assert!(
        !(eku.any
            || eku.client_auth
            || eku.code_signing
            || eku.email_protection
            || eku.time_stamping
            || eku.ocsp_signing
            || !eku.other.is_empty()),
        "serverAuth only"
    );
    assert!(!leaf_cert.is_ca());

    // A name that is not a host name is refused at minting.
    assert!(ca.leaf("not a name").is_err());
}

fn find_private_keys(dir: &Path, found: &mut Vec<String>) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            find_private_keys(&path, found);
        } else if String::from_utf8_lossy(&std::fs::read(&path).unwrap()).contains("PRIVATE KEY") {
            found.push(path.display().to_string());
        }
    }
}

/// T4: the CA files are created new with mode 0600; an existing file or a link at either path is
/// refused and the link's target is untouched; no private key is written by `write_files`. The
/// bundle holds the run CA first and at least 21 roots (the system store).
#[cfg(unix)]
#[test]
fn ca_files_are_new_0600_and_never_follow_a_link() {
    use std::os::unix::fs::PermissionsExt as _;
    let ca = RunCa::mint(&subtrees()).unwrap();
    let dir = tempfile::tempdir().unwrap();
    ca.write_files(dir.path()).unwrap();
    for name in [RUN_CA_FILE, BUNDLE_FILE] {
        let mode = std::fs::metadata(dir.path().join(name))
            .unwrap()
            .permissions()
            .mode()
            & 0o777;
        assert_eq!(mode, 0o600, "{name}");
    }
    let mut keys = Vec::new();
    find_private_keys(dir.path(), &mut keys);
    assert!(keys.is_empty(), "a private key was written: {keys:?}");
    let kept = certificates(&std::fs::read(dir.path().join(BUNDLE_FILE)).unwrap());
    assert_eq!(kept[0], ca.cert_der().to_vec(), "the run CA is first");
    assert!(kept.len() >= 21, "only {} certificates", kept.len());

    // Every file already there: refused, and the content is not replaced.
    let before = std::fs::read(dir.path().join(RUN_CA_FILE)).unwrap();
    assert!(ca.write_files(dir.path()).is_err());
    assert_eq!(std::fs::read(dir.path().join(RUN_CA_FILE)).unwrap(), before);

    // A link at either path: refused, the target is never created or written.
    for linked in [RUN_CA_FILE, BUNDLE_FILE] {
        let entry = tempfile::tempdir().unwrap();
        let elsewhere = tempfile::tempdir().unwrap();
        let target = elsewhere.path().join("victim");
        std::os::unix::fs::symlink(&target, entry.path().join(linked)).unwrap();
        assert!(ca.write_files(entry.path()).is_err(), "{linked}");
        assert!(!target.exists(), "{linked}: the link was followed");
    }
    let elsewhere = tempfile::tempdir().unwrap();
    let target = elsewhere.path().join("victim");
    std::fs::write(&target, b"keep").unwrap();
    let entry = tempfile::tempdir().unwrap();
    std::os::unix::fs::symlink(&target, entry.path().join(RUN_CA_FILE)).unwrap();
    assert!(ca.write_files(entry.path()).is_err());
    assert_eq!(std::fs::read(&target).unwrap(), b"keep");
}

/// T5 (old `the_bundle_holds_certificates_only_with_the_proxy_ca_first`): the bundle is the run
/// CA first, then certificates only, each re-encoded from its DER. The old test fed a source
/// holding a key to `bundle_pem`, which is private now; the same filter is `certificates`, which
/// the bundle is built through, and the written file is checked for what it must not hold. A
/// source with no certificate yields none (old `a_store_without_a_root_is_refused`; the refusal
/// itself is inside the private builder, so only the filter is asserted).
#[test]
fn bundle_holds_certificates_only_with_the_run_ca_first() {
    let ca = RunCa::mint(&subtrees()).unwrap();
    let other = RunCa::mint(&["example.org".to_string()]).unwrap();
    let key = "-----BEGIN PRIVATE KEY-----\nAAAA\n-----END PRIVATE KEY-----\n";
    let source = format!(
        "comment line\n{key}{root}-----BEGIN TRUSTED CERTIFICATE-----\nAAAA\n\
         -----END TRUSTED CERTIFICATE-----\n-----BEGIN CERTIFICATE-----\nnot base64!\n\
         -----END CERTIFICATE-----\n-----BEGIN CERTIFICATE-----\nMIIBAAAA\n\
         -----END CERTIFICATE-----\n{key}",
        root = other.export().cert,
    );
    assert_eq!(
        certificates(source.as_bytes()),
        [other.cert_der().to_vec()],
        "only the block that parses survives"
    );

    // A source with a key and no certificate yields none (the builder refuses it).
    assert!(certificates(key.as_bytes()).is_empty());
    assert!(certificates(b"").is_empty());

    let dir = tempfile::tempdir().unwrap();
    ca.write_files(dir.path()).unwrap();
    let text = std::fs::read_to_string(dir.path().join(BUNDLE_FILE)).unwrap();
    for banned in ["PRIVATE", "TRUSTED", "comment"] {
        assert!(!text.contains(banned), "{banned}");
    }
    let kept = certificates(text.as_bytes());
    assert_eq!(kept[0], ca.cert_der().to_vec(), "the run CA is first");
    assert_eq!(
        text.matches("-----BEGIN CERTIFICATE-----").count(),
        kept.len()
    );
    assert!(text.lines().all(|l| l.len() <= 64));
}

#[cfg(target_os = "linux")]
fn succeeded(code: std::process::ExitCode) -> bool {
    format!("{code:?}") == format!("{:?}", std::process::ExitCode::SUCCESS)
}

/// One real watchdog boot (recorder: this binary, server off) over an entry folder made by
/// `prepare`; the harness copies the key file's mode to `mode` while it runs.
#[cfg(target_os = "linux")]
fn boot(entry: &Path, mode: &Path) -> std::process::ExitCode {
    use goalcup::connector::{ConnectorRef, HomeLock, HostList, LaunchPlan, NativeSources, builtin};
    use goalcup::watchdog::{CaPem, StartFacts, run_with};
    let hosts = HostList::from_file(builtin::HOSTS.as_bytes(), "model-hosts.toml").unwrap();
    let key = entry.join("rec/run-ca.key");
    let script = format!("stat -c %a {} > {}", key.display(), mode.display());
    let connector = ConnectorRef { id: "fake".into(), name: "Fake".into(), sha256: "0".repeat(64), source: Default::default() };
    let facts = StartFacts {
        run: "r0123456789abcdef".into(), entry: "e0123456789abcdef".into(), segment: 0,
        entry_dir: entry.to_path_buf(), deadline: None, server_time: None, local_wall: 0,
        workspace: entry.to_path_buf(), connector: serde_json::to_value(&connector).unwrap(),
        harness_version: None, keep: true, build: None, hosts: serde_json::to_value(&hosts).unwrap(),
        hosts_sha256: hosts.sha256().to_string(), native: serde_json::to_value(NativeSources::default()).unwrap(),
        mask_rules: serde_json::json!([]), values: serde_json::json!([]),
        ca: CaPem { cert: String::new(), key: String::new() }, prev: None, harness: None, null_since: None, notes: Vec::new(),
    };
    let plan = LaunchPlan {
        connector, harness_version: None, program: "/bin/sh".into(), argv: vec!["-c".into(), script],
        env: [("PATH".to_string(), "/usr/bin:/bin".to_string())].into(), home: entry.join("home"),
        lock: HomeLock::default(), before: vec![], after: vec![], ca_env: vec![], hosts,
        native: NativeSources::default(), mask_rules: vec![], secret_values: vec![], notes: vec![],
        unread: vec![], log: vec![], refusal: None,
    };
    // SAFETY: nextest runs each test in its own process, before any thread of it starts.
    unsafe { std::env::set_var("GOALCUP_SERVER", "off") };
    run_with(plan, facts, Path::new(env!("CARGO_BIN_EXE_goalcup")))
}

/// T4, the key half (PRD-02 `rec/run-ca.key`): created new with mode 0600, no PRIVATE KEY block
/// anywhere else in the entry folder, gone at the seal; a planted symlink or hardlink is never
/// followed or written through, and the boot is refused rather than recording without it.
#[cfg(target_os = "linux")]
#[test]
fn run_ca_key_is_new_0600_gone_at_the_seal_and_never_follows_a_link() {
    use std::os::unix::fs::symlink;
    let prepare = |tmp: &tempfile::TempDir| {
        let home = tmp.path().join("g");
        let run_dir = goalcup::cli::run_dir(&home, "r0123456789abcdef");
        let entry = goalcup::cli::entry_dir(&home, "r0123456789abcdef", "e0123456789abcdef");
        std::fs::create_dir_all(entry.join("rec")).unwrap();
        let server = serde_json::json!({"v": 1, "server": null, "run": "r0123456789abcdef", "mode": "practice",
            "deadline": null, "repo": null, "connector": {"id": "fake", "name": "Fake", "source": "builtin"},
            "hosts_file": null, "entries": [{"id": "e0123456789abcdef", "harness_version": null, "resumed": false}]});
        std::fs::write(goalcup::cli::server_json(&run_dir), server.to_string()).unwrap();
        entry
    };
    let tmp = tempfile::tempdir().unwrap();
    let entry = prepare(&tmp);
    let mode = tmp.path().join("mode");
    assert!(succeeded(boot(&entry, &mode)));
    assert_eq!(std::fs::read_to_string(&mode).unwrap().trim(), "600");
    assert!(!entry.join("rec/run-ca.key").exists(), "the key outlived the seal");
    let mut keys = Vec::new();
    find_private_keys(&entry, &mut keys);
    assert!(keys.is_empty(), "a private key was left: {keys:?}");

    for hard in [false, true] {
        let tmp = tempfile::tempdir().unwrap();
        let entry = prepare(&tmp);
        let victim = tmp.path().join("victim");
        std::fs::write(&victim, b"keep").unwrap();
        let planted = entry.join("rec/run-ca.key");
        if hard { std::fs::hard_link(&victim, &planted) } else { symlink(&victim, &planted) }.unwrap();
        assert!(!succeeded(boot(&entry, &tmp.path().join("mode"))), "hard={hard}");
        assert_eq!(std::fs::read(&victim).unwrap(), b"keep", "hard={hard}: written through");
    }
}
